<?php
$title='Templates & Design';$subtitle='AI report prompts, messages and the look of your PDF reports';
$types=Seed::types();
$t=$_GET['t']??'report_website';
if($t!=='design'&&!isset($types[$t]))$t='report_website';
if(is_post()){
  $a=$_POST['a']??'';$id=(int)($_POST['id']??0);
  $pt=isset($types[$_POST['type']??''])?$_POST['type']:$t;
  try{
  if($a==='save'){
    $d=['type'=>$pt,'name'=>mb_substr(trim($_POST['name']??'Untitled'),0,180)?:'Untitled','subject'=>mb_substr(trim($_POST['subject']??''),0,250),'content'=>trim($_POST['content']??'')];
    if($d['content']==='')throw new Exception('Content cannot be empty.');
    if($id)DB::update('prompts',$d,'id=?',[$id]);else{$id=DB::insert('prompts',$d);}
    if(!empty($_POST['use'])||!DB::val('SELECT COUNT(*) FROM prompts WHERE type=? AND is_active=1',[$pt])){DB::q('UPDATE prompts SET is_active=(id=?) WHERE type=?',[$id,$pt]);}
    flash('Saved.');redirect(url('templates',['t'=>$pt,'id'=>$id]));}
  if($a==='use'){$p=DB::row('SELECT type FROM prompts WHERE id=?',[$id]);if($p)DB::q('UPDATE prompts SET is_active=(id=?) WHERE type=?',[$id,$p['type']]);flash('Now in use.');redirect(url('templates',['t'=>$p['type']??$t,'id'=>$id]));}
  if($a==='dup'){$p=DB::row('SELECT * FROM prompts WHERE id=?',[$id]);if($p){$n=DB::insert('prompts',['type'=>$p['type'],'name'=>$p['name'].' (copy)','subject'=>$p['subject'],'content'=>$p['content']]);foreach(DB::all('SELECT * FROM assets WHERE prompt_id=?',[$id]) as $as)DB::insert('assets',['name'=>$as['name'],'file'=>$as['file'],'placement'=>$as['placement'],'prompt_id'=>$n]);redirect(url('templates',['t'=>$p['type'],'id'=>$n]));}}
  if($a==='delete'){$p=DB::row('SELECT * FROM prompts WHERE id=?',[$id]);if($p&&$p['is_active'])throw new Exception('You cannot delete the prompt in use. Set another one in use first.');if($p){DB::q('DELETE FROM prompts WHERE id=?',[$id]);DB::q('UPDATE assets SET prompt_id=NULL WHERE prompt_id=?',[$id]);flash('Deleted.');}redirect(url('templates',['t'=>$t]));}
  if($a==='reset'){foreach(Seed::prompts() as [$ty,$n,$s,$c])if($ty===$t){$nid=DB::insert('prompts',['type'=>$ty,'name'=>$n.' ('.date('d M').')','subject'=>$s,'content'=>$c,'is_default'=>1]);redirect(url('templates',['t'=>$t,'id'=>$nid]));}}
  if($a==='upload'){
    $files=$_FILES['art']??null;$n=0;
    if(!$files||empty($files['name'][0]))throw new Exception('Choose one or more images.');
    @mkdir(ROOT.'/assets/uploads/doodles',0755,true);
    foreach($files['name'] as $i=>$nm){
      if(!is_uploaded_file($files['tmp_name'][$i]))continue;
      $ext=strtolower(pathinfo($nm,PATHINFO_EXTENSION));
      if(!in_array($ext,['png','jpg','jpeg','webp','svg'],true))continue;
      if($ext==='svg'&&preg_match('~<script|\bon\w+\s*=|javascript:|<foreignObject|<iframe|<embed|<object|<!ENTITY|<use[^>]+href=["\']?(?!#)~i',file_get_contents($files['tmp_name'][$i])))continue;
      $dst='assets/uploads/doodles/'.token(6).'.'.$ext;
      move_uploaded_file($files['tmp_name'][$i],ROOT.'/'.$dst);
      DB::insert('assets',['name'=>mb_substr(trim($_POST['name']??'')?:pathinfo($nm,PATHINFO_FILENAME),0,150),'file'=>$dst,'placement'=>isset(Report::PLACES[$_POST['placement']??''])?$_POST['placement']:'any','prompt_id'=>(int)($_POST['prompt_id']??0)?:null]);$n++;}
    flash($n.' illustration(s) uploaded.');back(url('templates',['t'=>'design']));}
  if($a==='delart'){$as=DB::row('SELECT * FROM assets WHERE id=?',[$id]);if($as){if(!DB::val('SELECT COUNT(*) FROM assets WHERE file=? AND id<>?',[$as['file'],$id]))@unlink(ROOT.'/'.$as['file']);DB::q('DELETE FROM assets WHERE id=?',[$id]);}flash('Illustration removed.');back(url('templates',['t'=>'design']));}
  if($a==='preview'){
    // Re-render the latest report (or sample content) with the current design – no AI cost
    $r=DB::row('SELECT * FROM reports ORDER BY id DESC LIMIT 1');
    $l=$r?DB::row('SELECT l.*,COALESCE(c.keyword,l.category) keyword FROM leads l LEFT JOIN campaigns c ON c.id=l.campaign_id WHERE l.id=?',[$r['lead_id']]):null;
    if(!$l)$l=['id'=>0,'name'=>'Sample Business','category'=>'Dental clinic','city'=>'Pune','address'=>'Baner, Pune','website'=>'https://example.com','rating'=>4.6,'reviews'=>120,'phone'=>'','email'=>'','keyword'=>'dentist','audit'=>'','position'=>3,'web_score'=>62,'map_score'=>71,'contact_name'=>''];
    $a2=jd($l['audit']);$d=$r?jd($r['html']):[];if(empty($d['summary']))$d=Report::sample();
    $hasWeb=!empty($l['website'])&&empty($a2['website']['meta']['down']);
    $pdf=Report::build($l,$a2,$d,$hasWeb,$l['id']?Report::competitors($l):[],(int)($_POST['prompt_id']??0));
    header('Content-Type: application/pdf');header('Content-Disposition: inline; filename="design-preview.pdf"');echo $pdf;exit;}
  }catch(Throwable $e){flash(e($e->getMessage()),'err');}
  back(url('templates',['t'=>$t]));}
$reportPrompts=DB::all("SELECT id,name,type FROM prompts WHERE type IN ('report_website','report_noweb') ORDER BY type,name");
?>
<div class="tabs"><?php foreach($types as $k=>[$lb]):?><a href="<?=url('templates',['t'=>$k])?>" class="<?=$t===$k?'on':''?>"><?=e($lb)?></a><?php endforeach?><a href="<?=url('templates',['t'=>'design'])?>" class="<?=$t==='design'?'on':''?>"><?=icon('image')?>Report design</a></div>
<?php if($t==='design'):$arts=DB::all('SELECT a.*,p.name pname FROM assets a LEFT JOIN prompts p ON p.id=a.prompt_id ORDER BY a.id DESC');$P=setting('brand_primary','#0B0B0B');$Ac=setting('brand_accent','#B8860B');?>
<div class="g3"><div class="col"><form method="post" enctype="multipart/form-data" class="card frm"><?=csrf_field()?><input type="hidden" name="a" value="upload"><div class="card-h"><h3><span class="hi hi-y"><?=icon('upload')?></span>Upload your illustrations</h3></div><p class="hint mt0">Add your own doodles, cartoons, mascots or photos. They replace the built-in artwork in the matching report section. PNG with a transparent background looks best (about 800×520 px).</p><label>Images<input type="file" name="art[]" accept=".png,.jpg,.jpeg,.webp,.svg" multiple required></label><label>Name (optional)<input name="name" placeholder="e.g. Mascot waving"></label><label>Use in section<select name="placement"><?php foreach(Report::PLACES as $k=>$lb):?><option value="<?=$k?>"><?=e($lb)?></option><?php endforeach?></select></label><label>Use with prompt<select name="prompt_id"><option value="">All report prompts</option><?php foreach($reportPrompts as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach?></select><small>Pick a prompt to give it its own visual style.</small></label><button class="btn btn-y"><?=icon('upload')?>Upload</button></form>
<div class="card"><div class="card-h"><h3><span class="hi hi-b"><?=icon('eye')?></span>Preview the design</h3></div><p class="hint mt0">Re-renders your latest report (or sample content) with the current colours, fonts and illustrations – no AI cost.</p><form method="post" target="_blank" class="frm"><?=csrf_field()?><input type="hidden" name="a" value="preview"><label>Illustration set<select name="prompt_id"><option value="0">Default (all prompts)</option><?php foreach($reportPrompts as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach?></select></label><button class="btn btn-n"><?=icon('file')?>Open preview PDF</button></form><p class="hint">Colours, fonts and logo: <a class="lnk" href="<?=url('settings',['tab'=>'branding'])?>">Settings → Branding</a></p></div></div>
<div class="col"><div class="card"><div class="card-h"><h3>Your illustrations</h3><span class="muted"><?=count($arts)?></span></div><?php if(!$arts):?><p class="muted sm">None yet – the built-in illustrations below are used.</p><?php else:?><div class="doodles"><?php foreach($arts as $as):?><div class="dd-i"><img src="<?=e($as['file'])?>" alt=""><b><?=e($as['name'])?></b><small><?=e(Report::PLACES[$as['placement']]??$as['placement'])?> · <?=e($as['pname']?:'all prompts')?></small><form method="post" onsubmit="return confirm('Remove this illustration?')"><?=csrf_field()?><input type="hidden" name="a" value="delart"><input type="hidden" name="id" value="<?=$as['id']?>"><button class="btn btn-xs mt"><?=icon('trash')?>Remove</button></form></div><?php endforeach?></div><?php endif?></div>
<div class="card"><div class="card-h"><h3>Built-in illustrations</h3><span class="muted sm">in your brand colours</span></div><div class="doodles"><?php foreach(Report::PLACES as $k=>$lb):if($k==='any')continue;?><div class="dd-i"><img src="<?=Illus::uri(Illus::get($k==='growth'?'growth':$k,$P,$Ac))?>" alt=""><b><?=e($lb)?></b></div><?php endforeach?></div></div></div></div>
<?php else:
$list=DB::all('SELECT * FROM prompts WHERE type=? ORDER BY is_active DESC,updated_at DESC',[$t]);
$cur=isset($_GET['id'])?($_GET['id']==='new'?['id'=>0,'name'=>'','subject'=>'','content'=>'','is_active'=>0]:DB::row('SELECT * FROM prompts WHERE id=? AND type=?',[(int)$_GET['id'],$t])):($list[0]??null);
$isAI=strpos($t,'report_')===0;$isMail=strpos($t,'email')===0;
$vars=['business_name','contact_name','first_name','category','city','address','phone','email','website','rating','reviews','keyword','report_link','booking_link','agency_name','agency_phone','agency_email','agency_website','sender_name','currency','currency_symbol','yearly_fee','website_fee'];
if($isAI)$vars=array_merge($vars,['web_score','map_score','web_categories','position','website_audit','map_audit','competitors','services']);
$myArts=$cur&&$cur['id']&&$isAI?DB::all('SELECT * FROM assets WHERE prompt_id=? ORDER BY placement',[$cur['id']]):[];
?>
<div class="g3"><div class="col"><div class="card"><div class="card-h"><h3><?=e($types[$t][0])?></h3><a class="btn btn-sm btn-y" href="<?=url('templates',['t'=>$t,'id'=>'new'])?>"><?=icon('plus')?>New</a></div><p class="hint mt0"><?=e($types[$t][1])?></p><div class="plist"><?php foreach($list as $p):?><a href="<?=url('templates',['t'=>$t,'id'=>$p['id']])?>" class="pi <?=$cur&&(int)$cur['id']===(int)$p['id']?'on':''?>"><b><?=e($p['name'])?></b><span><?=$p['is_active']?'<span class="bdg bdg-green">In use</span>':'<span class="bdg bdg-gray">Saved</span>'?><small><?=ago($p['updated_at'])?></small></span></a><?php endforeach?></div><form method="post" onsubmit="return confirm('Add a fresh copy of the default for this type?')"><?=csrf_field()?><input type="hidden" name="a" value="reset"><button class="btn btn-sm mt"><?=icon('refresh')?>Restore default as new</button></form></div>
<div class="card"><div class="card-h"><h3>Placeholders</h3></div><p class="hint mt0">Click to copy. They are filled in for every business.</p><div class="vars"><?php foreach($vars as $v):?><code onclick="A.copy('{{<?=$v?>}}')">{{<?=$v?>}}</code><?php endforeach?></div><?php if(!$isAI):?><p class="hint mt">Keep the first message simple – no fees. The PDF is attached to the email and WhatsApp message itself, so no link is needed.</p><?php else:?><p class="hint mt">Your prompt guides the tone and focus. The AI always answers in a fixed structure (summary, market stats with sources, findings, opportunity, plan, quick wins). Setu then designs the landscape PDF – cover, score gauges, charts, competitor graphs, illustrations and your branding – automatically.</p><?php endif?></div></div>
<div class="col"><?php if($cur):?><form method="post" class="card frm"><?=csrf_field()?><input type="hidden" name="a" value="save"><input type="hidden" name="id" value="<?=(int)$cur['id']?>"><input type="hidden" name="type" value="<?=e($t)?>"><div class="card-h"><h3><?=$cur['id']?'Edit':'New'?> <?=$isAI?'AI prompt':'message'?></h3><?php if($cur['id']):?><span><?=$cur['is_active']?'<span class="bdg bdg-green">In use</span>':'<span class="bdg bdg-gray">Saved</span>'?></span><?php endif?></div><label>Name<input name="name" value="<?=e($cur['name'])?>" required></label><?php if($isMail):?><label>Email subject<input name="subject" value="<?=e($cur['subject'])?>"></label><?php endif?><label><?=$isAI?'Prompt sent to the AI':'Message text'?><textarea name="content" rows="<?=$isAI?26:14?>" class="mono" required><?=e($cur['content'])?></textarea></label><label class="chk"><input type="checkbox" name="use" value="1" <?=$cur['is_active']?'checked':''?>> Use this <?=$isAI?'prompt':'message'?> (in use)</label><div class="row"><button class="btn btn-y"><?=icon('check')?>Save</button></div></form>
<?php if($cur['id']):?><div class="row"><?php if(!$cur['is_active']):?><form method="post"><?=csrf_field()?><input type="hidden" name="a" value="use"><input type="hidden" name="id" value="<?=$cur['id']?>"><button class="btn"><?=icon('check')?>Set in use</button></form><?php endif?><form method="post"><?=csrf_field()?><input type="hidden" name="a" value="dup"><input type="hidden" name="id" value="<?=$cur['id']?>"><button class="btn"><?=icon('copy')?>Duplicate</button></form><?php if(!$cur['is_active']):?><form method="post" onsubmit="return confirm('Delete this prompt?')"><?=csrf_field()?><input type="hidden" name="a" value="delete"><input type="hidden" name="id" value="<?=$cur['id']?>"><button class="btn btn-r"><?=icon('trash')?>Delete</button></form><?php endif?></div>
<?php if($isAI):?><form method="post" enctype="multipart/form-data" class="card frm mt"><?=csrf_field()?><input type="hidden" name="a" value="upload"><input type="hidden" name="prompt_id" value="<?=$cur['id']?>"><div class="card-h"><h3><span class="hi hi-y"><?=icon('image')?></span>Illustrations for this prompt</h3><a class="lnk" href="<?=url('templates',['t'=>'design'])?>">All illustrations</a></div><?php if($myArts):?><div class="doodles"><?php foreach($myArts as $as):?><div class="dd-i"><img src="<?=e($as['file'])?>" alt=""><b><?=e($as['name'])?></b><small><?=e(Report::PLACES[$as['placement']]??'')?></small></div><?php endforeach?></div><?php else:?><p class="hint mt0">Upload company-specific doodles or cartoons that should appear only in reports written with this prompt.</p><?php endif?><div class="row mt"><input type="file" name="art[]" accept=".png,.jpg,.jpeg,.webp,.svg" multiple required><select name="placement" style="max-width:200px"><?php foreach(Report::PLACES as $k=>$lb):?><option value="<?=$k?>"><?=e($lb)?></option><?php endforeach?></select><button class="btn btn-n"><?=icon('upload')?>Upload</button></div></form><?php endif?>
<?php endif?><?php else:?><div class="card empty"><?=icon('msg','eic')?><p>Select or create a prompt.</p></div><?php endif?></div></div>
<?php endif;
